wc={'A':'T','T':'A','G':'C','C':'G'}
def best_hairpin(s, i0, i1, min_stem=6):
    """i0,i1 0-based window. Find left arm start a and right arm end b with >=min_stem WC pairs."""
    best=[]
    for a in range(i0,i1):
        for b in range(i1-1, a+2*min_stem+3, -1):
            m=0
            while a+m < b-m and wc[s[a+m]]==s[b-m]:
                m+=1
            if m>=min_stem:
                loop=b-a-1-2*m
                if 3<=loop<=60:
                    best.append((m,a+1,b+1-m,loop,b+1))
    best.sort(key=lambda x:-x[0])
    return best[:3]
for name,(i0,i1) in {'5p flank 1050-1165':(1049,1165),'3p flank 2178-2300':(2177,2300),'whole':(0,n)}.items():
