def hairpin(s,a,b,ms=6):
    out=[]
    for i in range(a,b):
        for j in range(b-1,i+2*ms+3,-1):
            m=0
            while i+m<j-m and wc[s[i+m]]==s[j-m]: m+=1
            if m>=ms:
                loop=j-i-1-2*m
                if 4<=loop<=60: out.append((m,i+1,j+1-m,loop))
    out.sort(key=lambda x:-x[0]); return out[:2]
